static Inet6Address linkLocal(byte[] mac) throws UnknownHostException {
  byte[] a = new byte[16];
  a[0] = (byte) 0xfe; a[1] = (byte) 0x80;              // fe80::/64
  a[8] = (byte) (mac[0] ^ 0x02); a[9] = mac[1]; a[10] = mac[2];
  a[11] = (byte) 0xff; a[12] = (byte) 0xfe;
  a[13] = mac[3]; a[14] = mac[4]; a[15] = mac[5];
  return (Inet6Address) InetAddress.getByAddress(a);
}
// Inet6Address.getHostAddress() zwróci postać nieskompresowaną (fe80:0:0:0:…); do wyświetlania można ją skompresować.
